package ai.hamza.edm;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Normalization is a parity contract with scripts/edm-index.py — these cases pin the
 * Java half. The cross-language half is pinned by EdmMatcherTest, which matches
 * against a fixture generated by the Python indexer.
 */
class FingerprinterTest {

    @Test
    void normalizesCaseWhitespaceAndUnicode() {
        assertThat(Fingerprinter.normalize("  Jane SMITH  ")).isEqualTo("jane smith");
        // NFC: e + combining acute composes to é.
        assertThat(Fingerprinter.normalize("José")).isEqualTo("josé");
    }

    @Test
    void digitHeavyValuesKeepDigitsOnly() {
        assertThat(Fingerprinter.normalize("4111 1111 1111 1001")).isEqualTo("4111111111111001");
        assertThat(Fingerprinter.normalize("+1 (555) 010-2030")).isEqualTo("15550102030");
    }

    @Test
    void mixedValuesAreNotDigitStripped() {
        assertThat(Fingerprinter.normalize("fake001@example-corp.test"))
                .isEqualTo("fake001@example-corp.test");
    }

    @Test
    void weakValuesAreRejected() {
        assertThat(Fingerprinter.strongEnough(Fingerprinter.normalize("abc"))).isFalse();
        assertThat(Fingerprinter.strongEnough(Fingerprinter.normalize("  1234  "))).isFalse();
        assertThat(Fingerprinter.strongEnough(Fingerprinter.normalize("jane smith"))).isTrue();
    }

    @Test
    void fingerprintIsDeterministicAndSaltDependent() {
        byte[] saltA = "salt-a".getBytes();
        byte[] saltB = "salt-b".getBytes();
        long a1 = Fingerprinter.fingerprint(saltA, "jane smith");
        long a2 = Fingerprinter.fingerprint(saltA, "jane smith");
        long b = Fingerprinter.fingerprint(saltB, "jane smith");
        assertThat(a1).isEqualTo(a2);
        assertThat(a1).isNotEqualTo(b);
    }
}
